struct spa_poll_event
    data::NTuple{12, UInt8}
end

function Base.getproperty(x::Ptr{spa_poll_event}, f::Symbol)
    f === :events && return Ptr{UInt32}(x + 0)
    f === :data && return Ptr{Ptr{Cvoid}}(x + 4)
    f === :data_u64 && return Ptr{UInt64}(x + 4)
    return getfield(x, f)
end

function Base.getproperty(x::spa_poll_event, f::Symbol)
    r = Ref{spa_poll_event}(x)
    ptr = Base.unsafe_convert(Ptr{spa_poll_event}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{spa_poll_event}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::spa_poll_event, private::Bool = false)
    (:events, :data, :data_u64, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

