"""
    pw_context_events

context events emitted by the context object added with pw_context_add_listener

| Field            | Note                                                |
| :--------------- | :-------------------------------------------------- |
| destroy          | The context is being destroyed                      |
| free             | The context is being freed                          |
| check\\_access   | a new client object is added                        |
| global\\_added   | a new global object was added                       |
| global\\_removed | a global object was removed                         |
| driver\\_added   | a driver was added, since 0.3.75 version:1          |
| driver\\_removed | a driver was removed, since 0.3.75 version:1        |
| recalc\\_graph   | recalculate the graph state, since 1.7.0 version:2  |
"""
struct pw_context_events
    version::UInt32
    destroy::Ptr{Cvoid}
    free::Ptr{Cvoid}
    check_access::Ptr{Cvoid}
    global_added::Ptr{Cvoid}
    global_removed::Ptr{Cvoid}
    driver_added::Ptr{Cvoid}
    driver_removed::Ptr{Cvoid}
    recalc_graph::Ptr{Cvoid}
end

