"""
    spa_choice_type

| Enumerator           | Note                                      |
| :------------------- | :---------------------------------------- |
| SPA\\_CHOICE\\_None  | no choice, first value is current         |
| SPA\\_CHOICE\\_Range | range: default, min, max                  |
| SPA\\_CHOICE\\_Step  | range with step: default, min, max, step  |
| SPA\\_CHOICE\\_Enum  | list: default, alternative,...            |
| SPA\\_CHOICE\\_Flags | flags: first value is flags               |
"""
const spa_choice_type = UInt32
const SPA_CHOICE_None = 0 % UInt32
const SPA_CHOICE_Range = 1 % UInt32
const SPA_CHOICE_Step = 2 % UInt32
const SPA_CHOICE_Enum = 3 % UInt32
const SPA_CHOICE_Flags = 4 % UInt32

