const SPA_META_ACQUISITION_DOMAIN_SIZE = 16 % UInt32
const SPA_META_ACQUISITION_PTP_CLOCK_ID_SIZE = 8 % UInt32
const SPA_META_FEATURE_ACQUISITION_VERSION_1 = 1 % UInt32
