"""
    spa_log_topic_enum

Enumeration of log topics in a plugin

\\since 1.1.0

| Field        | Note                             |
| :----------- | :------------------------------- |
| topics       | Array of pointers to log topics  |
| topics\\_end | End of topics array              |
"""
struct spa_log_topic_enum
    version::UInt32
    topics::Ptr{Ptr{spa_log_topic}}
    topics_end::Ptr{Ptr{spa_log_topic}}
end

"""
    spa_log_methods

| Field        | Note                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| :----------- | :--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |
| log          | Log a message with the given log level.  !!! note      If compiled with this header, this function is only called for implementations of version 0. For versions 1 and above, see logt() instead.  # Arguments * `log`: a [`spa_log`](@ref) * `level`: a [`spa_log_level`](@ref) * `file`: the file name * `line`: the line number * `func`: the function name * `fmt`: printf style format * `...`: format arguments                          |
| logv         | Log a message with the given log level.  !!! note      If compiled with this header, this function is only called for implementations of version 0. For versions 1 and above, see logtv() instead.  # Arguments * `log`: a [`spa_log`](@ref) * `level`: a [`spa_log_level`](@ref) * `file`: the file name * `line`: the line number * `func`: the function name * `fmt`: printf style format * `args`: format arguments                        |
| logt         | Log a message with the given log level for the given topic.  !!! note      Callers that do not use topic-based logging (version 0), the *topic* is NULL  \\since 1  # Arguments * `log`: a [`spa_log`](@ref) * `level`: a [`spa_log_level`](@ref) * `topic`: the topic for this message, may be NULL * `file`: the file name * `line`: the line number * `func`: the function name * `fmt`: printf style format * `...`: format arguments      |
| logtv        | Log a message with the given log level for the given topic.  !!! note      For callers that do not use topic-based logging (version 0), the *topic* is NULL  \\since 1  # Arguments * `log`: a [`spa_log`](@ref) * `level`: a [`spa_log_level`](@ref) * `topic`: the topic for this message, may be NULL * `file`: the file name * `line`: the line number * `func`: the function name * `fmt`: printf style format * `args`: format arguments |
| topic\\_init | Initializes a spa_log_topic to the correct logging level.  !!! compat "Deprecated"      Plugin host should obtain log topics from SPA_LOG_TOPIC_ENUM_NAME and update them itself.  \\since 1                                                                                                                                                                                                                                                   |
"""
struct spa_log_methods
    data::NTuple{48, UInt8}
end

function Base.getproperty(x::Ptr{spa_log_methods}, f::Symbol)
    f === :version && return Ptr{UInt32}(x + 0)
    f === :log && return Ptr{Ptr{Cvoid}}(x + 8)
    f === :logv && return Ptr{Ptr{Cvoid}}(x + 16)
    f === :logt && return Ptr{Ptr{Cvoid}}(x + 24)
    f === :logtv && return Ptr{Ptr{Cvoid}}(x + 32)
    f === :topic_init && return Ptr{Ptr{Cvoid}}(x + 40)
    return getfield(x, f)
end

function Base.getproperty(x::spa_log_methods, f::Symbol)
    r = Ref{spa_log_methods}(x)
    ptr = Base.unsafe_convert(Ptr{spa_log_methods}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{spa_log_methods}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::spa_log_methods, private::Bool = false)
    (:version, :log, :logv, :logt, :logtv, :topic_init, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

