"""
    pw_map_item

An entry in the map. This is used internally only. Each element in the backing [`pw_array`](@ref) is a union [`pw_map_item`](@ref). For real items, the data pointer points to the item. If an element has been removed, [`pw_map`](@ref)->free\\_list is the index of the most recently removed item. That item contains the index of the next removed item until item->next is [`SPA_ID_INVALID`](@ref).

The free list is prepended only, the last item to be removed will be the first item to get re-used on the next insert.
"""
struct pw_map_item
    data::NTuple{8, UInt8}
end

function Base.getproperty(x::Ptr{pw_map_item}, f::Symbol)
    f === :next && return Ptr{Csize_t}(x + 0)
    f === :data && return Ptr{Ptr{Cvoid}}(x + 0)
    return getfield(x, f)
end

function Base.getproperty(x::pw_map_item, f::Symbol)
    r = Ref{pw_map_item}(x)
    ptr = Base.unsafe_convert(Ptr{pw_map_item}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{pw_map_item}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::pw_map_item, private::Bool = false)
    (:next, :data, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

"""
    pw_map

A map. This struct should be treated as opaque by the caller.
"""
struct pw_map
    items::pw_array
    free_list::UInt32
end

