    version::UInt32
    destroy::Ptr{Cvoid}
    state_changed::Ptr{Cvoid}
    control_info::Ptr{Cvoid}
    io_changed::Ptr{Cvoid}
    param_changed::Ptr{Cvoid}
    add_buffer::Ptr{Cvoid}
    remove_buffer::Ptr{Cvoid}
    process::Ptr{Cvoid}
    drained::Ptr{Cvoid}
    command::Ptr{Cvoid}
